<script setup lang="ts">
import ListPager from '../../components/ListPager.vue'
import {useListPage} from '../../composables/useListPage'
import {statusLabel} from '../../utils/statusLabels'
import {apiCollection} from '../../api/collections'
import { computed, onMounted, reactive, ref } from 'vue'
import { api, ApiError, readableApiError } from '../../api/client'
import AMapCampus from '../../components/AMapCampus.vue'

type Location={id:number;name:string}
type Staff={id:number;username:string;display_name:string;role:string}
type Member={id:number;user_id:number;username:string;display_name:string;can_review:boolean;can_handover:boolean}
type Station={id:number;name:string;location:{id:number;name:string};address:string;opening_hours:Record<string,string>;capacity:number;status:string;contact_phone:string;latitude:number|null;longitude:number|null;approval_status:string;review_note:string;is_active:boolean;members:Member[]}
type Application={id:number;organization_name:string;applicant_name:string;official_email:string;campus_name:string;intended_locations:string;evidence_url:string;statement:string;status:string;review_note:string}

const stations=ref<Station[]>([]),locations=ref<Location[]>([]),staff=ref<Staff[]>([]),applications=ref<Application[]>([])
const loading=ref(true),busy=ref(false),error=ref(''),success=ref(''),editingId=ref<number|null>(null)
const form=reactive({name:'',location_id:'',address:'',weekdays:'08:30-17:30',weekends:'',capacity:100,status:'OPEN',contact_phone:'',latitude:null as number|null,longitude:null as number|null,is_active:true})
const member=reactive({user_id:'',can_review:true,can_handover:true})
const selected= computed(()=>stations.value.find(entry=>entry.id===editingId.value)??null)
const point=computed(()=>form.latitude==null||form.longitude==null?[]:[{latitude:form.latitude,longitude:form.longitude,label:form.name||'服务站',coordinate_system:'GCJ02' as const}])

async function load(){loading.value=true;error.value='';try{const [s,m,u,a]=await Promise.all([apiCollection<{data:{items:Station[]}}>('/admin/stations/?page_size=100'),api<{data:{locations:Location[]}}>('/items/metadata/'),apiCollection<{data:{items:Staff[]}}>('/admin/users/?page_size=100'),apiCollection<{data:{items:Application[]}}>('/admin/station-applications/?page_size=100')]);stations.value=s.data.items;locations.value=m.data.locations;staff.value=u.data.items.filter(entry=>entry.role!=='ADMIN');applications.value=a.data.items}catch(reason){error.value=readableApiError(reason,'站点管理数据加载失败')}finally{loading.value=false}}
function reset(){editingId.value=null;Object.assign(form,{name:'',location_id:String(locations.value[0]?.id??''),address:'',weekdays:'08:30-17:30',weekends:'',capacity:100,status:'OPEN',contact_phone:'',latitude:null,longitude:null,is_active:true})}
function edit(entry:Station){editingId.value=entry.id;Object.assign(form,{name:entry.name,location_id:String(entry.location.id),address:entry.address,weekdays:entry.opening_hours.weekdays??'',weekends:entry.opening_hours.weekends??'',capacity:entry.capacity,status:entry.status,contact_phone:entry.contact_phone??'',latitude:entry.latitude==null?null:Number(entry.latitude),longitude:entry.longitude==null?null:Number(entry.longitude),is_active:entry.is_active})}
async function save(){busy.value=true;error.value='';success.value='';try{const payload={...form,location_id:Number(form.location_id),opening_hours:{weekdays:form.weekdays,weekends:form.weekends},coordinate_system:'GCJ02'};if(editingId.value)await api(`/admin/stations/${editingId.value}/`,{method:'PATCH',body:JSON.stringify(payload)});else await api('/admin/stations/',{method:'POST',body:JSON.stringify(payload)});success.value='站点资料已保存';await load();reset()}catch(reason){error.value=readableApiError(reason,'保存失败')}finally{busy.value=false}}
async function act(id:number,action:'submit'|'decision',decision=''){busy.value=true;try{await api(`/admin/stations/${id}/${action}/`,{method:'POST',body:decision?JSON.stringify({decision}):undefined});await load()}catch(reason){error.value=readableApiError(reason,'操作失败')}finally{busy.value=false}}
async function runStationAction(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await work();await load()}catch(reason){error.value=readableApiError(reason,'操作失败，请重试。')}finally{busy.value=false}}
async function addMember(){if(!selected.value||!member.user_id)return;await runStationAction(async()=>{await api(`/admin/stations/${selected.value!.id}/members/`,{method:'POST',body:JSON.stringify({...member,user_id:Number(member.user_id)})})})}
async function removeMember(id:number){if(!selected.value)return;await runStationAction(async()=>{await api(`/admin/stations/${selected.value!.id}/members/`,{method:'DELETE',body:JSON.stringify({membership_id:id})})})}
async function decideApplication(id:number,decision:string){await runStationAction(async()=>{await api(`/admin/station-applications/${id}/decision/`,{method:'POST',body:JSON.stringify({decision})})})}
function pick(value:{latitude:number;longitude:number}){form.latitude=value.latitude;form.longitude=value.longitude}
onMounted(async()=>{await load();reset()})
const {page:pagedManagedStationsPage,rows:pagedManagedStations}=useListPage(stations)
const {page:applicationPage,rows:pagedApplications}=useListPage(applications)
</script>

<template><div class="page station-admin"><header><div><h1 class="page-title">真实服务站接入</h1><p class="page-lead">地图只记录位置；站点必须经平台审核后才对外展示和接受预约。</p></div></header><p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p><p v-if="loading" class="empty">正在读取…</p><template v-else><section class="layout"><form class="panel station-form" @submit.prevent="save"><h2>{{editingId?'编辑站点':'新增站点'}}</h2><label>站点名称<input v-model="form.name" required placeholder="例如：保卫处失物招领点"/></label><label>所属校区区域<select v-model="form.location_id" required><option v-for="entry in locations" :key="entry.id" :value="String(entry.id)">{{entry.name}}</option></select></label><label>详细地址<input v-model="form.address" required/></label><div class="two"><label>工作日时间<input v-model="form.weekdays" required/></label><label>周末时间<input v-model="form.weekends" placeholder="休息或 09:00-12:00"/></label></div><div class="two"><label>联系电话<input v-model="form.contact_phone"/></label><label>保管容量<input v-model.number="form.capacity" type="number" min="1" required/></label></div><div class="two"><label>服务状态<select v-model="form.status"><option value="OPEN">开放</option><option value="BUSY">繁忙</option><option value="CLOSED">暂停服务</option></select></label><label class="check"><input v-model="form.is_active" type="checkbox"/>启用站点</label></div><AMapCampus pickable compact :selected-coordinate-points="point" @pick="pick"/><p class="coords">GCJ-02：{{form.longitude??'未选'}}，{{form.latitude??'未选'}}</p><footer><button v-if="editingId" type="button" class="button button-ghost" @click="reset">取消</button><button class="button button-brand" :disabled="busy">保存站点资料</button></footer></form><div class="station-list"><article v-for="entry in pagedManagedStations" :key="entry.id" class="panel station"><div><span class="status-tag">{{statusLabel(entry.approval_status)}} / {{statusLabel(entry.status)}}</span><h2>{{entry.name}}</h2><p>{{entry.location.name}} · {{entry.address}}</p></div><div class="actions"><button class="button button-ghost" @click="edit(entry)">编辑</button><button v-if="['DRAFT','REJECTED'].includes(entry.approval_status)" class="button button-brand" @click="act(entry.id,'submit')">提交审核</button><button v-if="entry.approval_status==='PENDING'" @click="act(entry.id,'decision','APPROVE')">审核通过</button></div><section v-if="editingId===entry.id" class="members"><h3>工作人员授权</h3><div v-for="m in entry.members" :key="m.id"><span>{{m.display_name}} · {{m.can_review?'可审核':''}} {{m.can_handover?'可交接':''}}</span><button @click="removeMember(m.id)">解除</button></div><form @submit.prevent="addMember"><select v-model="member.user_id" required><option value="">选择协调员</option><option v-for="u in staff" :key="u.id" :value="String(u.id)">{{u.display_name}} (@{{u.username}})</option></select><label><input v-model="member.can_review" type="checkbox"/>认领审核</label><label><input v-model="member.can_handover" type="checkbox"/>现场交接</label><button class="button button-ghost">授权</button></form></section></article><ListPager :page="pagedManagedStationsPage" :total="stations.length" @change="pagedManagedStationsPage=$event"/><p v-if="!stations.length" class="empty">当前校区还没有站点，请在左侧新增。</p></div></section><section class="applications"><h2>学校接入申请</h2><article v-for="entry in pagedApplications" :key="entry.id" class="panel application"><div><span>{{statusLabel(entry.status)}} · {{entry.campus_name}}</span><h3>{{entry.organization_name}}</h3><p>{{entry.applicant_name}} · {{entry.official_email}}</p><p>{{entry.intended_locations}}</p><a :href="entry.evidence_url" target="_blank" rel="noopener">查看官方证明</a></div><div v-if="entry.status==='PENDING'" class="actions"><button @click="decideApplication(entry.id,'REJECT')">驳回</button><button class="button button-brand" @click="decideApplication(entry.id,'APPROVE')">通过核验</button></div></article><ListPager :page="applicationPage" :total="applications.length" @change="applicationPage=$event"/><p v-if="!applications.length" class="empty">暂无待处理的学校接入申请。</p></section></template></div></template>

<style scoped>.layout{display:grid;grid-template-columns:minmax(420px,1fr) 1fr;gap:18px;margin-top:32px}.station-form{display:grid;gap:14px;padding:24px;align-self:start}.station-form h2{margin:0}.station-form label{display:grid;gap:6px;color:var(--ct-text-muted);font-size:12px}.station-form input,.station-form select,.members select{padding:11px;border:1px solid var(--ct-border);border-radius:9px;background:var(--ct-bg-soft);color:var(--ct-text)}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.check{display:flex!important;align-items:center}.check input{width:auto}.coords{font-family:monospace;color:var(--ct-text-muted)}footer,.actions{display:flex;justify-content:flex-end;gap:8px}.station-list,.applications{display:grid;gap:12px}.station{padding:20px;box-shadow:none}.station h2{margin:10px 0 5px}.station p,.application p{color:var(--ct-text-muted)}.members{margin-top:16px;padding-top:14px;border-top:1px solid var(--ct-border)}.members>div,.members>form{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px}.applications{margin-top:34px}.application{display:flex;justify-content:space-between;gap:20px;padding:20px}.notice{padding:12px;border-radius:10px}.error{color:var(--ct-danger);background:#ad343412}.success{color:var(--ct-success);background:#36644b12}.empty{display:grid;place-items:center;min-height:180px;color:var(--ct-text-muted);border:1px dashed var(--ct-border);border-radius:14px}@media(max-width:900px){.layout{grid-template-columns:1fr}.application{flex-direction:column}}@media(max-width:600px){.two{grid-template-columns:1fr}.members>form{align-items:flex-start;flex-direction:column}}</style>
